add_shortcode( 'in_stock_products', 'perfectpixel_in_stock_products_shortcode' );
add_filter( 'woocommerce_shortcode_products_query', 'perfectpixel_in_stock_products_query', 10, 3 );

function perfectpixel_in_stock_products_shortcode( $atts ) {
	if ( ! class_exists( 'WC_Shortcode_Products' ) ) {
		return '';
	}
	$atts            = (array) $atts;
	$atts['class']   = trim( ( $atts['class'] ?? '' ) . ' perfectpixel-in-stock' );
	$shortcode       = new WC_Shortcode_Products( $atts, 'products' );
	return $shortcode->get_content();
}

// Out-of-stock products carry the "outofstock" product_visibility term.
function perfectpixel_in_stock_products_query( $args, $atts, $type ) {
	if ( false !== strpos( (string) ( $atts['class'] ?? '' ), 'perfectpixel-in-stock' ) ) {
		$args['tax_query'][] = array(
			'taxonomy' => 'product_visibility',
			'field'    => 'name',
			'terms'    => array( 'outofstock' ),
			'operator' => 'NOT IN',
		);
	}
	return $args;
}
